// L-function Visualization Shader

#define PI 3.14159265359

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Normalize coordinates
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / min(iResolution.x, iResolution.y);

    // Parameters
    float p = 99.0;
    float q = 2.0;
    float logRatio = log(p)/log(q);
    float time = iTime * 1.5;

    // Initialize color
    vec3 col = vec3(0.0);

    // Complex position
    vec2 z = uv * 4.0;

    // Lattice contribution
    for(float k = -3.0; k <= 3.0; k++) {
        for(float m = -3.0; m <= 3.0; m++) {
            float angle = 2.0 * PI * m * logRatio + time;
            float radius = k * logRatio;

            vec2 latticePoint = exp(radius) * vec2(cos(angle), sin(angle));
            float dist = length(z - latticePoint);

            // Add glow effect
            col += 0.01 / (dist * dist) * vec3(0.2, 0.5, 1.0);

            // Add orbital trails
            float orbitDist = abs(length(z) - exp(radius));
            col += 0.02 / (orbitDist * orbitDist) * 
                  vec3(0.5 + 0.5 * sin(k * 0.5),
                       0.5 + 0.5 * cos(m * 0.3),
                       0.5 + 0.5 * sin(time + k * m * 0.1));
        }
    }

    // Add spiral flow
    float spiralAngle = atan(z.y, z.x);
    float spiralRadius = length(z);
    float spiralPhase = spiralAngle * logRatio + log(spiralRadius);
    col += 0.2 * vec3(0.5 + 0.5 * cos(spiralPhase + time * 2.0 + vec3(0,2,4)));

    // Add wave interference
    float wave = 0.0;
    for(float k = -2.0; k <= 2.0; k++) {
        float angle = k * logRatio + time;
        wave += sin(dot(z, vec2(cos(angle), sin(angle))) * 2.0 * PI);
    }
    col += 0.1 * vec3(0.5 + 0.5 * wave);

    // Add vector field visualization
    vec2 field = vec2(3.0);
    for(float k = -2.0; k <= 2.0; k++) {
        float angle = k * logRatio + time;
        field += vec2(cos(angle + atan(z.y, z.x)),
                     sin(angle + atan(z.y, z.x)));
    }
    float fieldStrength = length(field);
    col += 0.1 * vec3(field.x, fieldStrength, field.y);

    // Add modular symmetry pattern
    float modular = 8.0;
    for(float k = -3.0; k <= 3.0; k++) {
        for(float m = -3.0; m <= 3.0; m++) {
            float angle = 2.0 * PI * m * logRatio + time;
            float radius = k * logRatio;
            vec2 modPoint = exp(radius) * vec2(cos(angle), sin(angle));
            modular += sin(length(z - modPoint) * 5.0 + time);
        }
    }
    col += 0.1 * vec3(0.5 + 0.5 * modular);

    // Tone mapping and gamma correction
    col = pow(col / (1.0 + col), vec3(0.4545));

    // Output final color
    fragColor = vec4(col, 1.0);
}
